// Article metadata registry for Dinh dưỡng Việt
// Single source of truth for all knowledge articles

export interface ArticleMeta {
  slug: string;
  title: string;
  description: string;
  emoji: string;
  category: 'guidelines' | 'disease' | 'special' | 'education' | string;
  categoryName: string;
  displayCategory?: 'bai-viet' | 'an-lanh-manh' | 'dang-co-benh' | 'mon-an' | 'thuc-don' | 'dung-tin-ngay';
  date: string; // ISO date
  readTime: number; // minutes
  featured?: boolean;
  tags?: string[];
  audience?: string[];
  priority?: string;
  specialty?: string;
  series?: string;
  sources?: { name: string; title?: string; description?: string; url: string; slug?: string }[]; // 3-5 nguồn uy tín
  keywords?: string[];
  reviewedAt?: string;
  nextReviewAt?: string;
  medicalReviewer?: string;
  evidenceLevel?: 'guideline' | 'systematic-review' | 'clinical-review' | 'general-reference';
}

